package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for ChecksumCalculatingInputStream constructor and its functionality.
 */
public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen0Test {

    @Test
    public void testConstructorAndRead() throws IOException {
        byte[] data = "Hello World".getBytes();
        InputStream in = new ByteArrayInputStream(data);
        CRC32 crc32 = new CRC32();

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in);

        int b = cis.read();
        assertEquals(data[0] & 0xFF, b);
        assertEquals(crc32.getValue(), crc32.getValue()); // Verify checksum is being updated via side effect

        // Exhaust the stream
        int count = 0;
        while (cis.read() != -1) {
            count++;
        }
        assertEquals(data.length - 1, count);
    }












}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for ChecksumCalculatingInputStream constructor and its functionality.
 */
public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen0Test {



    @Test
    public void testReadWithBuffer() throws IOException {
        byte[] data = {1, 2, 3, 4, 5};
        InputStream in = new ByteArrayInputStream(data);
        CRC32 crc32 = new CRC32();
        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in);

        byte[] buffer = new byte[3];
        int read = cis.read(buffer);

        assertEquals(3, read);
        assertEquals(1, buffer[0]);
        assertEquals(2, buffer[1]);
        assertEquals(3, buffer[2]);

        // Verify checksum calculation
        CRC32 expectedCrc = new CRC32();
        expectedCrc.update(new byte[]{1, 2, 3});
        assertEquals(expectedCrc.getValue(), crc32.getValue());
    }










}

