package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for ChecksumCalculatingInputStream constructor and its functionality.
 */
public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen0Test {







    @Test
    public void testSkip() throws IOException {
        byte[] data = {1, 2, 3, 4, 5, 6, 7, 8};
        InputStream in = new ByteArrayInputStream(data);
        CRC32 crc32 = new CRC32();
        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in);

        long skipped = cis.skip(3);
        assertEquals(3, skipped);

        // After skipping 3, the next read should be 4
        assertEquals(4, cis.read());

        // Checksum should have updated with 1, 2, 3
        CRC32 expectedCrc = new CRC32();
        expectedCrc.update(new byte[]{1, 2, 3});
        assertEquals(expectedCrc.getValue(), crc32.getValue());
    }






}

